/* ===================================================================
   PTU Sheet — Pokémon Tabletop United 1.05 character sheet helper
   Data: window.PTU_DATA (species, moves, abilities, natures, items,
   classes, features, edges, pokeEdges)
=================================================================== */
"use strict";
const D = window.PTU_DATA || {};
const $  = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];

/* ---------- reference constants ---------- */
/* Virtuoso is a homebrew Rank above Master. It deliberately does NOT add dice — a Virtuoso
   Skill Check is still 6d6, exactly like Master. What it changes is the Rank *number*: it
   counts as Rank 8, which is what anything phrased "… + your Rank in <Skill>" reads (Mentor
   skill sums, Channeling capacity, chef/craft scaling, Rank-gated prerequisites). Hence the
   two helpers diverging below; everything downstream already goes through one or the other. */
const RANKS = ["Pathetic", "Untrained", "Novice", "Adept", "Expert", "Master", "Virtuoso"];
const RANK_NUM_OVERRIDE = { Virtuoso: 8 };                        // skips 7 on purpose — campaign ruling
const rankNum  = r => RANK_NUM_OVERRIDE[r] ?? Math.max(1, RANKS.indexOf(r) + 1);  // Pathetic=1 … Master=6, Virtuoso=8
const rankDice = r => Math.min(6, rankNum(r));                    // #d6 — never more than Master's 6d6

/* The Edge that unlocks Virtuoso. It lives here rather than in data/edges.json because a
   tools/build_data.py rebuild regenerates that file from the xlsx and would drop it — the same
   reason the Legendary Auras/Gifts are defined in app.js. Merged into D.edges (right after the
   other Skill Edges) so it shows up in the Edges list, the Level-Up pickers and the Reference. */
const VIRTUOSO_LEVEL = 20;
const VIRTUOSO_EDGE = {
  name: "Virtuoso Skills",
  category: "Skill Edges",
  prerequisites: `Level ${VIRTUOSO_LEVEL}, Master Rank in the Skill`,
  effect: "You Rank Up a Skill from Master to Virtuoso. A Virtuoso Skill Check still rolls 6d6, "
        + "the same as Master — but the Skill counts as Rank 8 for any effect that scales with "
        + "your Rank in it. You may take this Edge multiple times, but only once per Skill. (Homebrew)",
};
if(Array.isArray(D.edges) && !D.edges.some(e=>e.name===VIRTUOSO_EDGE.name)){
  const after = D.edges.findIndex(e=>e.name==="Master Skills");
  D.edges.splice(after<0 ? D.edges.length : after+1, 0, VIRTUOSO_EDGE);
}
/* Virtuoso is the one gated Rank: Level 20+ AND the Edge (GM 🔓 unlock bypasses both). */
function virtuosoOk(t){
  if(!t) return false;
  if(t.unlocked) return true;
  return (t.level||1) >= VIRTUOSO_LEVEL
      && (t.edges||[]).some(e => String(e).trim().toLowerCase() === "virtuoso skills");
}
function rankAllowed(t, rank){ return rank !== "Virtuoso" || virtuosoOk(t); }
const VIRTUOSO_LOCK_MSG = `Virtuoso needs Level ${VIRTUOSO_LEVEL} and the “Virtuoso Skills” Edge (or GM 🔓).`;

const SKILLS = [
  ["acrobatics","Acrobatics"], ["athletics","Athletics"], ["combat","Combat"],
  ["stealth","Stealth"], ["perception","Perception"], ["intimidate","Intimidate"],
  ["survival","Survival"], ["generalEd","General Ed."], ["medicineEd","Medicine Ed."],
  ["occultEd","Occult Ed."], ["pokemonEd","Pokémon Ed."], ["technologyEd","Technology Ed."],
  ["guile","Guile"], ["charm","Charm"], ["command","Command"],
  ["focus","Focus"], ["intuition","Intuition"],
];
const STATS = [["hp","HP"],["atk","Attack"],["def","Defense"],
  ["spatk","Sp.Atk"],["spdef","Sp.Def"],["spd","Speed"]];
/* Berserker Feature names (Game of Throhs pp.48-49). The automation itself lives in the BERSERKER
   block down by the weapon code — only the names are up here, above `let state = load()`, because
   injuryHPCount reads BERSERKER_LESSONS from inside trainerDerived. A const declared further down
   would still be in its temporal dead zone if load() ever reached the derived layer, and load()
   swallows exceptions — the same trap the LU_* constants are hoisted for. */
const BERSERKER_LESSONS  = "Lessons In Rage & Pain";
const BERSERKER_PUSH     = "Push it to the Limit";
const BERSERKER_FIGHT_ON = "Fight On and On";
const BERSERKER_FRENZY   = "Frenzy";
/* Skill Categories (Core p.62) — used by the Categoric Inclination Edge's +1 bonus */
const SKILL_CATEGORY = {
  acrobatics:"Body", athletics:"Body", combat:"Body", stealth:"Body",
  perception:"Mind", generalEd:"Mind", medicineEd:"Mind", occultEd:"Mind", pokemonEd:"Mind", technologyEd:"Mind",
  intimidate:"Spirit", survival:"Spirit", guile:"Spirit", charm:"Spirit", command:"Spirit", focus:"Spirit", intuition:"Spirit",
};
/* +1 to every Skill Check in the chosen Category, if the trainer has the Edge and picked one */
function categoricBonus(t, skillKey){
  return (t.edges||[]).includes("Categoric Inclination") && t.categoricInclination
    && SKILL_CATEGORY[skillKey]===t.categoricInclination ? 1 : 0;
}

