        if(!already && !t.unlocked && (def.bindAP||0) > free){ toast(`Not enough AP \u2014 ${def.feat} Binds ${def.bindAP}, you have ${Math.max(0,free)} free`); return; }
        if(!trainerModes(t)) t.modes = {};
